package io.lumine.mythic.lib.api.crafting.uifilters;
import io.lumine.mythic.lib.api.util.ui.*; import net.minecraft.item.ItemStack; import java.util.*;
public interface UIFilter { String getIdentifier(); boolean matches(ItemStack stack,String argument,String data,FriendlyFeedbackProvider feedback); boolean isValid(String argument,String data,FriendlyFeedbackProvider feedback); default ArrayList<String> tabCompleteArgument(String a){return new ArrayList<>();} default ArrayList<String> tabCompleteData(String a,String d){return new ArrayList<>();} default boolean fullyDefinesItem(){return false;} default ItemStack getItemStack(String argument,String data,FriendlyFeedbackProvider feedback){return ItemStack.EMPTY;} default ItemStack getDisplayStack(String argument,String data,FriendlyFeedbackProvider feedback){return getItemStack(argument,data,feedback);} default ArrayList<String> getDescription(String argument,String data){return new ArrayList<>(List.of(getIdentifier()+":"+argument));} default String getSourcePlugin(){return "MythicLib";} default String getFilterName(){return getIdentifier();} default String exampleArgument(){return "";} default String exampleData(){return "";} }
